CREATE TABLE `Customers` (`customer_id` DECIMAL(18,2), `customer_first_name` VARCHAR(100), `customer_middle_initial` VARCHAR(100), `customer_last_name` VARCHAR(100), `gender` VARCHAR(100), `email_address` VARCHAR(100), `login_name` VARCHAR(100), `login_password` VARCHAR(100), `phone_number` VARCHAR(100), `town_city` VARCHAR(100), `state_county_province` VARCHAR(100), `country` VARCHAR(100));
CREATE TABLE `Orders` (`order_id` DECIMAL(18,2), `customer_id` DECIMAL(18,2), `date_order_placed` DATETIME, `order_details` VARCHAR(100));
CREATE TABLE `Invoices` (`invoice_number` DECIMAL(18,2), `order_id` DECIMAL(18,2), `invoice_date` DATETIME);
CREATE TABLE `Accounts` (`account_id` DECIMAL(18,2), `customer_id` DECIMAL(18,2), `date_account_opened` DATETIME, `account_name` VARCHAR(100), `other_account_details` VARCHAR(100));
CREATE TABLE `Product_Categories` (`production_type_code` VARCHAR(100), `product_type_description` VARCHAR(100), `vat_rating` DECIMAL(18,2));
CREATE TABLE `Products` (`product_id` DECIMAL(18,2), `parent_product_id` DECIMAL(18,2), `production_type_code` VARCHAR(100), `unit_price` DECIMAL(18,2), `product_name` VARCHAR(100), `product_color` VARCHAR(100), `product_size` VARCHAR(100));
CREATE TABLE `Financial_Transactions` (`transaction_id` DECIMAL(18,2), `account_id` DECIMAL(18,2), `invoice_number` DECIMAL(18,2), `transaction_type` VARCHAR(100), `transaction_date` DATETIME, `transaction_amount` DECIMAL(18,2), `transaction_comment` VARCHAR(100), `other_transaction_details` VARCHAR(100));
CREATE TABLE `Order_Items` (`order_item_id` DECIMAL(18,2), `order_id` DECIMAL(18,2), `product_id` DECIMAL(18,2), `product_quantity` VARCHAR(100), `other_order_item_details` VARCHAR(100));
CREATE TABLE `Invoice_Line_Items` (`order_item_id` DECIMAL(18,2), `invoice_number` DECIMAL(18,2), `product_id` DECIMAL(18,2), `product_title` VARCHAR(100), `product_quantity` VARCHAR(100), `product_price` DECIMAL(18,2), `derived_product_cost` DECIMAL(18,2), `derived_vat_payable` DECIMAL(18,2), `derived_total_cost` DECIMAL(18,2));
